import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';

const registerWeatherTool = (registry: ToolRegistry, execute: (input: Record<string, unknown>) => Promise<string>) => {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    execute
  );
};

describe('ToolRegistry input validation', () => {
  it('returns a required property rejection without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    registerWeatherTool(registry, executor);

    const response = await registry.execute('get_weather', {});
    expect({result: response.result, calls: executor.mock.calls.length}).toMatchObject({
      result: expect.stringMatching(/location.*required/i),
      calls: 0,
    });
  });

  it('compiles a static tool schema once across repeated executions', async () => {
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    const registry = new ToolRegistry();
    registry.register(
      {name: 'get_weather', description: 'Get weather', inputSchema: {type: 'object'}},
      async () => 'sunny'
    );

    for (let call = 0; call < 10; call++) await registry.execute('get_weather', {});

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });

  it('validates each function-valued tool definition against its current schema', async () => {
    const registry = new ToolRegistry();
    let definitionCalls = 0;
    registry.register(
      () => {
        definitionCalls += 1;
        const property = definitionCalls <= 2 ? 'first' : 'second';
        return {
          name: 'dynamic_tool',
          description: 'A dynamic tool',
          inputSchema: {
            type: 'object',
            properties: {[property]: {type: 'string'}},
            required: [property],
          },
        };
      },
      async () => 'ok'
    );

    const first = await registry.execute('dynamic_tool', {first: 'one'});
    const second = await registry.execute('dynamic_tool', {second: 'two'});

    expect([first.result, second.result]).toEqual(['ok', 'ok']);
  });

  it('passes valid input with extra properties unchanged to the executor', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', unit: 'celsius'};
    const executor = jest.fn(async (received: Record<string, unknown>) => JSON.stringify(received));
    registerWeatherTool(registry, executor);

    await registry.execute('get_weather', input);

    expect(executor.mock.calls).toEqual([[input]]);
  });

  it('rejects a wrong-typed property without returning its value', async () => {
    const registry = new ToolRegistry();
    const secret = 3817;
    const executor = jest.fn(async () => 'sunny');
    registerWeatherTool(registry, executor);

    const logLine = jest.spyOn(console, 'log').mockImplementation(() => {});
    const response = await registry.execute('get_weather', {location: secret as unknown as string});

    expect({
      result: response.result,
      logs: logLine.mock.calls.length,
      calls: executor.mock.calls.length,
      namesPathAndExpectedType: /\/location.*string/i.test(response.result),
    }).toMatchObject({
      result: expect.not.stringContaining(String(secret)),
      logs: 0,
      calls: 0,
      namesPathAndExpectedType: true,
    });
    logLine.mockRestore();
  });

  it('rejects a value outside the declared enum', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather',
        inputSchema: {type: 'object', properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}}},
      },
      executor
    );

    const response = await registry.execute('get_weather', {unit: 'kelvin'});

    expect({result: response.result, calls: executor.mock.calls.length}).toMatchObject({
      result: expect.stringMatching(/\/unit.*enum.*celsius.*fahrenheit/i),
      calls: 0,
    });
  });
});
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import {log} from '../../shared/logger.js';

const validator = new Ajv({strict: false, validateFormats: false} as unknown as ConstructorParameters<typeof Ajv>[0]);

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  staticValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  private getDynamicValidator(schema: object): ValidateFunction {
    const cached = this.dynamicValidators.get(schema);
    if (cached) return cached;
    const validate = validator.compile(schema);
    this.dynamicValidators.set(schema, validate);
    return validate;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const stored: StoredTool = {definitionSource: definition, execute};
    if (typeof definition !== 'function') {
      try {
        stored.staticValidator = validator.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool ${resolved.name}: ${String(error)}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, stored);
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Returns schema rejections as ToolResponses; only unknown tool names throw (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    let validate = tool.staticValidator;
    if (!validate) {
      validate = this.getDynamicValidator(definition.inputSchema);
    }
    if (!validate(input)) {
      const error = validate.errors?.[0] as (ErrorObject & {instancePath?: string}) | undefined;
      const params = error?.params as Record<string, unknown> | undefined;
      const path =
        `${error?.instancePath ?? ''}${error?.keyword === 'required' ? `/${String(params?.missingProperty ?? '')}` : ''}` ||
        '/';
      const constraint =
        error?.keyword === 'required'
          ? 'is required'
          : error?.keyword === 'type'
            ? `must be ${String(params?.type ?? 'valid')}`
            : error?.keyword === 'enum'
              ? `must match one of enum values: ${Array.isArray(params?.allowedValues) ? params.allowedValues.map(String).join(', ') : 'the declared values'}`
              : `failed ${String(error?.keyword ?? 'schema')} validation`;
      return {result: `${path} ${constraint}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
